package com.makemytrip.makemytrip.models;
import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.index.Indexed;import org.springframework.data.mongodb.core.mapping.Document;import java.util.List;
@Document("rooms") public class Room {@Id private String id;@Indexed private String hotelId;private String roomType;private String roomIdentifier;private double price;private int capacity;private List<String> amenities;private List<String> images;private int availableQuantity;private boolean premium;private double upgradePrice;public String getId(){return id;}public String getHotelId(){return hotelId;}public void setHotelId(String x){hotelId=x;}public String getRoomType(){return roomType;}public void setRoomType(String x){roomType=x;}public String getRoomIdentifier(){return roomIdentifier;}public void setRoomIdentifier(String x){roomIdentifier=x;}public double getPrice(){return price;}public void setPrice(double x){price=x;}public int getCapacity(){return capacity;}public void setCapacity(int x){capacity=x;}public List<String> getAmenities(){return amenities;}public void setAmenities(List<String>x){amenities=x;}public List<String> getImages(){return images;}public void setImages(List<String>x){images=x;}public int getAvailableQuantity(){return availableQuantity;}public void setAvailableQuantity(int x){availableQuantity=x;}public boolean isPremium(){return premium;}public void setPremium(boolean x){premium=x;}public double getUpgradePrice(){return upgradePrice;}public void setUpgradePrice(double x){upgradePrice=x;}}
